import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 급여계산이 끝난 지급일의 상태 목록 (등록·마감취소는 계산 미완료로 본다)
const CALCULATED_STATUSES = ['계산완료', '과세집계완료', '마감', '전표처리'];
// 가정: 이체 상태는 입력 문서에 출처가 없어 지급일 상태로 정한다. 마감·전표처리면 이체완료, 그 전이면 이체대기
const TRANSFERRED_STATUSES = ['마감', '전표처리'];
const TRANSFER_DONE = '이체완료';
const TRANSFER_WAITING = '이체대기';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isIntegerText(value: unknown): boolean {
  return /^[0-9]+$/.test(String(value ?? '').trim());
}

@Controller('api/v1')
export class FnSfr02104Controller {
  @Get('/payrolls/transfers')
  async listPayrollTransfers(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const query = checks.queryOf(req.query);

    const paydayIdRaw = query['paydayId'];
    if (paydayIdRaw === undefined || paydayIdRaw === null || String(paydayIdRaw).trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 지급일을 선택해 주세요.');
    }
    if (!isIntegerText(paydayIdRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 지급일 ID 형식이 올바르지 않습니다.');
    }
    const paydayId = String(paydayIdRaw).trim();

    const employeeIdRaw = query['employeeId'];
    let employeeId: string | null = null;
    if (employeeIdRaw !== undefined && employeeIdRaw !== null && String(employeeIdRaw).trim() !== '') {
      if (!isIntegerText(employeeIdRaw)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '임직원 ID 형식이 올바르지 않습니다.');
      }
      employeeId = String(employeeIdRaw).trim();
    }

    let page = 0;
    const pageRaw = query['page'];
    if (pageRaw !== undefined && pageRaw !== null && String(pageRaw).trim() !== '') {
      if (!isIntegerText(pageRaw)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 형식이 올바르지 않습니다.');
      }
      page = Number(String(pageRaw).trim());
    }

    let size = DEFAULT_SIZE;
    const sizeRaw = query['size'];
    if (sizeRaw !== undefined && sizeRaw !== null && String(sizeRaw).trim() !== '') {
      if (!isIntegerText(sizeRaw) || Number(String(sizeRaw).trim()) < 1) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기 형식이 올바르지 않습니다.');
      }
      size = Math.min(Number(String(sizeRaw).trim()), MAX_SIZE);
    }

    return transaction(async (db) => {
      const paydays = await db.query(
        'SELECT status AS "status" FROM payday WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      if (paydays.length === 0) {
        throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
      }
      const paydayStatus = String(paydays[0].status);
      if (!CALCULATED_STATUSES.includes(paydayStatus)) {
        throw new ApiError(422, 'PAYROLL_NOT_CALCULATED', '급여계산이 완료되지 않은 지급일입니다.');
      }
      const transferStatus = TRANSFERRED_STATUSES.includes(paydayStatus) ? TRANSFER_DONE : TRANSFER_WAITING;

      const params = { paydayId, employeeId, size, offset: page * size };
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM payroll p WHERE p.payday_id = CAST(:paydayId AS bigint) AND (CAST(:employeeId AS bigint) IS NULL OR p.employee_id = CAST(:employeeId AS bigint))',
        { paydayId, employeeId },
      );
      const total = Number(counts[0].total);

      const rows = await db.query(
        'SELECT p.payroll_id AS "payrollId", p.employee_id AS "employeeId", p.net_pay_amount AS "netPayAmount" FROM payroll p WHERE p.payday_id = CAST(:paydayId AS bigint) AND (CAST(:employeeId AS bigint) IS NULL OR p.employee_id = CAST(:employeeId AS bigint)) ORDER BY p.payroll_id LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        params,
      );

      const items = rows.map((row: Record<string, unknown>) => ({
        payrollId: Number(row.payrollId),
        employeeId: Number(row.employeeId),
        netPayAmount: row.netPayAmount === null || row.netPayAmount === undefined ? null : Number(row.netPayAmount),
        transferStatus,
      }));

      return { items, page, size, total };
    });
  }
}

