import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr02104Page({ role, notify }: PageProps) {
  const [paydayId, setPaydayId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<{ paydayId: number | string; employeeId: number | string }>({
    paydayId: '',
    employeeId: '',
  });
  const [page, setPage] = useState(0);
  const [formError, setFormError] = useState('');
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page>(async () => {
    if (applied.paydayId === '') {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/payrolls/transfers', role, undefined, {
      paydayId: applied.paydayId,
      employeeId: applied.employeeId,
      page,
      size: SIZE,
    });
  }, [applied, page, role]);

  const items = data ? data.items : [];
  const total = data ? data.total : 0;
  const pageSum = items.reduce((sum, row) => sum + Number(row['netPayAmount'] ?? 0), 0);

  function search() {
    if (paydayId === '') {
      setFormError('급여 지급일을 선택해 주세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ paydayId, employeeId });
  }

  function reset() {
    setPaydayId('');
    setEmployeeId('');
    setFormError('');
    setPage(0);
    setApplied({ paydayId: '', employeeId: '' });
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Tiles items={[['급여이체 대상', <Num value={total} />]]} />
      </section>
      <section className="box span-4">
        <h2>실수령액 합계</h2>
        <Tiles items={[['현재 쪽 합계', <Num value={pageSum} />]]} />
      </section>
      <section className="box span-4">
        <h2>조회 기준</h2>
        <Tiles items={[['급여 지급일', applied.paydayId === '' ? '-' : <RefName table="payday" role={role} value={applied.paydayId} />]]} />
      </section>
      <section className="box span-12">
        <h2>급여이체 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="급여 지급일 ID" required>
            <LookupSelect table="payday" role={role} value={paydayId} onChange={setPaydayId} placeholder="지급일 선택" />
          </Field>
          <Field label="임직원 ID">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} placeholder="전체" />
          </Field>
        </Filters>
        {formError !== '' && <ErrorText text={formError} />}
        {error !== '' && <ErrorText text={error} />}
        <Band total={total} />
        <DataTable
          columns={[
            { key: 'payrollId', label: '급여 ID' },
            {
              key: 'employeeId',
              label: '임직원 ID',
              render: (row) => <RefName table="employee" role={role} value={row['employeeId']} />,
            },
            { key: 'netPayAmount', label: '실수령액', render: (row) => <Num value={row['netPayAmount']} /> },
            { key: 'transferStatus', label: '이체 상태', render: (row) => <Badge value={row['transferStatus']} /> },
          ]}
          rows={items}
          onRowClick={(row) => setSelected(row)}
          empty={loading ? '불러오는 중입니다.' : applied.paydayId === '' ? '급여 지급일을 선택하고 조회해 주세요.' : '조회된 이체 내역이 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {selected && (
        <Drawer title="급여이체 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['급여 ID', String(selected['payrollId'] ?? '')],
              ['임직원 ID', <RefName table="employee" role={role} value={selected['employeeId']} />],
              ['실수령액', <Num value={selected['netPayAmount']} />],
              ['이체 상태', <Badge value={selected['transferStatus']} />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
